# Keys Claude may change via `portfolio.cli config set`. Anything not listed is human-only.
# max_step = largest absolute change per application; cooldown_days = min days between changes of the same key.
version: 1
max_changes_per_week: 2
keys:
  portfolio.gross_target:            {min: 0.30,  max: 1.00, max_step: 0.10, cooldown_days: 7}
  portfolio.n_positions:             {min: 10,    max: 30,   max_step: 5,    cooldown_days: 14}
  portfolio.max_weight:              {min: 0.02,  max: 0.08, max_step: 0.01, cooldown_days: 7}
  portfolio.rebalance_band:          {min: 0.005, max: 0.03, max_step: 0.01, cooldown_days: 7}
  portfolio.vol_target_annual:       {min: 0.08,  max: 0.18, max_step: 0.02, cooldown_days: 7}
  signals.weights.residual_reversal: {min: 0.0,   max: 1.0,  max_step: 0.2,  cooldown_days: 14}
  signals.weights.pead:              {min: 0.0,   max: 1.0,  max_step: 0.2,  cooldown_days: 14}
  execution.limit_offset_bps:        {min: 0,     max: 30,   max_step: 10,   cooldown_days: 7}
  execution.max_turnover_daily:      {min: 0.10,  max: 0.40, max_step: 0.10, cooldown_days: 7}
# Human-only (engine refuses `config set`): mode, execution.enabled, execution.style, execution.window_et,
# universe_file, risk.*, shorts, leverage, broker.*, notify.*

"""portfolio/cli.py - the ONLY code path that talks to Alpaca. Deterministic, idempotent, logged.
Exit codes: 0 ok | 1 failure | 2 auth invalid | 3 not a trading day | 4 halted | 5 data unavailable
"""
from __future__ import annotations
import argparse, fcntl, hashlib, json, os, sys
from datetime import date, datetime, time, timedelta
from pathlib import Path
from zoneinfo import ZoneInfo
from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parents[1]
STATE = ROOT / "state"
ET = ZoneInfo("America/New_York")
EXIT_OK, EXIT_FAIL, EXIT_AUTH, EXIT_CLOSED, EXIT_HALTED, EXIT_DATA = 0, 1, 2, 3, 4, 5
LIVE_PHRASE = "I understand this trades real money"
CLAIM_TTL = timedelta(minutes=20)


def now_et() -> datetime:
    return datetime.now(ET)


def load_broker_env(cfg: dict) -> None:
    load_dotenv(Path(os.path.expanduser(cfg["broker"]["env_file"])), override=False)  # values are never logged


def paper_credentials(cfg: dict) -> tuple[str, str] | None:
    key = next((os.environ[n] for n in cfg["broker"]["key_env_names"] if os.environ.get(n)), None)
    sec = next((os.environ[n] for n in cfg["broker"]["secret_env_names"] if os.environ.get(n)), None)
    return (key, sec) if key and sec else None


def live_gate_passed(cfg: dict, args) -> bool:
    """Triple gate. Claude is forbidden from satisfying any leg; nothing here defaults to live."""
    armed = STATE / "LIVE_ARMED"
    return bool(
        getattr(args, "live", False)
        and cfg.get("mode") == "live"
        and armed.exists()
        and armed.read_text().strip() == LIVE_PHRASE
        and (now_et().timestamp() - armed.stat().st_mtime) < 24 * 3600
        and os.environ.get("ALPACA_LIVE_KEY")
        and os.environ.get("ALPACA_LIVE_SECRET")
    )


def trading_client(cfg: dict, args):
    """Returns (client, is_paper). paper=True is hardcoded on the non-live path."""
    from alpaca.trading.client import TradingClient
    if live_gate_passed(cfg, args):
        return TradingClient(os.environ["ALPACA_LIVE_KEY"], os.environ["ALPACA_LIVE_SECRET"], paper=False), False
    creds = paper_credentials(cfg)
    if creds is None:
        return None, True
    return TradingClient(creds[0], creds[1], paper=True), True


def assert_paper(client):
    acct = client.get_account()
    if not str(acct.account_number).startswith("PA"):
        raise SystemExit("refusing: account does not look like an Alpaca paper account")
    return acct


class RunLock:
    def __enter__(self):
        STATE.mkdir(parents=True, exist_ok=True)
        self.fh = open(STATE / ".engine.lock", "w")
        fcntl.flock(self.fh, fcntl.LOCK_EX)
        return self

    def __exit__(self, *exc):
        fcntl.flock(self.fh, fcntl.LOCK_UN)
        self.fh.close()


def halted() -> dict | None:
    if (STATE / "KILL_SWITCH").exists():
        return {"class": "human", "reason": "state/KILL_SWITCH present"}
    p = STATE / "halt.json"
    return json.loads(p.read_text()) if p.exists() else None


def run_record(d: date) -> dict:
    p = STATE / "runs" / f"{d.isoformat()}.json"
    return json.loads(p.read_text()) if p.exists() else {"date": d.isoformat(), "status": "none", "notes": []}


def save_run(rec: dict) -> None:
    p = STATE / "runs" / f"{rec['date']}.json"
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(rec, indent=2, sort_keys=True))
    tmp.replace(p)  # atomic


def in_exec_window(cfg: dict) -> bool:
    lo, hi = (time.fromisoformat(t) for t in cfg["execution"]["window_et"])
    return lo <= now_et().time() <= hi


def client_order_id(d: date, symbol: str, side: str) -> str:
    return f"cp-{d:%Y%m%d}-{symbol}-{side.upper()}"  # one order per symbol/side/day => idempotent by construction


def plan_hash(orders: list[dict], config_hash: str) -> str:
    return hashlib.sha256(json.dumps([orders, config_hash], sort_keys=True).encode()).hexdigest()[:16]


def claim_active(rec: dict) -> bool:
    exp = rec.get("claim_expires_at")
    return bool(exp) and datetime.fromisoformat(exp) > now_et()


def cmd_claim(cfg: dict, args) -> int:
    with RunLock():
        rec = run_record(now_et().date())
        if rec["status"] in ("executed", "vetoed", "halted"):
            print(json.dumps(rec)); return EXIT_OK
        rec.update(status="reviewing", claimed_by=args.by, claim_expires_at=(now_et() + CLAIM_TTL).isoformat())
        save_run(rec); print(json.dumps(rec)); return EXIT_OK


def cmd_execute(cfg: dict, args) -> int:
    d = date.fromisoformat(args.plan_date)
    with RunLock():
        h = halted()
        if h:
            print(json.dumps({"halted": h})); return EXIT_HALTED
        if not cfg["execution"]["enabled"]:
            print(json.dumps({"skipped": "execution.enabled is false (shadow soak)"})); return EXIT_OK
        if d != now_et().date():
            print("refusing: plan date is not today (ET)"); return EXIT_FAIL
        rec = run_record(d)
        if rec["status"] == "executed":
            print(json.dumps(rec)); return EXIT_OK  # idempotent re-run
        if rec["status"] in ("vetoed", "halted"):
            print(json.dumps(rec)); return EXIT_HALTED
        if getattr(args, "if_unreviewed", False) and (rec.get("reviewed_by") or claim_active(rec)):
            print(json.dumps({"deferred": "supervisor reviewing or already reviewed"})); return EXIT_OK
        if not in_exec_window(cfg):
            rec["notes"].append(f"execute refused outside window at {now_et():%H:%M} ET"); save_run(rec); return EXIT_FAIL
        plan = json.loads((STATE / "orders" / f"{d.isoformat()}.plan.json").read_text())
        if plan["plan_hash"] != plan_hash(plan["orders"], plan["config_hash"]):
            print("refusing: plan hash mismatch"); return EXIT_FAIL
        from portfolio.risk import check_plan  # deterministic checks re-run here; the supervisor's review is additive
        result = check_plan(cfg, plan)
        if result["hard_failures"]:
            rec.update(status="failed"); rec["notes"] += result["hard_failures"]; save_run(rec); return EXIT_FAIL
        client, is_paper = trading_client(cfg, args)
        if client is None:
            return EXIT_AUTH
        acct = assert_paper(client) if is_paper else client.get_account()
        from portfolio.broker import todays_client_order_ids, submit_marketable_limit
        from portfolio.ledger import ledger_has, ledger_append
        existing = todays_client_order_ids(client, d)
        excluded = set(args.exclude or [])
        submitted = 0
        for o in plan["orders"]:
            coid = client_order_id(d, o["symbol"], o["side"])
            if o["symbol"] in excluded:
                ledger_append({**o, "client_order_id": coid, "status": "excluded", "by": args.by, "reason": args.reason}); continue
            if coid in existing or ledger_has(coid):
                continue  # never double-submit
            res = submit_marketable_limit(client, cfg, o, coid)  # DAY limit; returns dict, never raises on reject
            ledger_append({**o, "client_order_id": coid, **res, "by": args.by})
            submitted += res["status"] != "rejected"
        rec.update(status="executed", executed_at=now_et().isoformat(), executor=args.by,
                   reviewed_by=args.by if args.by == "claude" else rec.get("reviewed_by"),
                   orders_submitted=submitted, orders_excluded=sorted(excluded), equity=float(acct.equity))
        if args.by != "claude":
            rec["notes"].append("EXECUTED_UNREVIEWED")
        save_run(rec); print(json.dumps(rec)); return EXIT_OK


def main(argv=None) -> int:
    from portfolio.config import load_config  # validates strategy.yaml against schema + bounds.yaml
    cfg = load_config(ROOT / "config" / "strategy.yaml")
    load_broker_env(cfg)
    p = argparse.ArgumentParser(prog="portfolio.cli")
    sub = p.add_subparsers(dest="cmd", required=True)
    e = sub.add_parser("execute"); e.add_argument("--plan-date", required=True); e.add_argument("--by", choices=["claude", "launchd", "human"], required=True)
    e.add_argument("--exclude", nargs="*"); e.add_argument("--reason", default=""); e.add_argument("--if-unreviewed", action="store_true"); e.add_argument("--live", action="store_true")
    c = sub.add_parser("claim"); c.add_argument("--by", required=True)
    # preflight, status, plan, check, veto, halt, resume, reconcile, report, weekly, config, escalate, selftest, auto: same pattern
    args = p.parse_args(argv)
    return {"execute": cmd_execute, "claim": cmd_claim}[args.cmd](cfg, args)


if __name__ == "__main__":
    sys.exit(main())
